figure.artwork:
child = spawn(verifier_cmd, timeout = 10_000ms) write(child.stdin, json(request)); close(child.stdin) status, out, err = wait(child) // out = stdout, err = stderr
if status != 0: reject("non-zero exit") // Sec 6 if timed_out(child): reject("timeout") // Sec 6 verdict = parse_single_json_object(out) // Sec 4; on any failure -> reject if verdict is null: reject("unparseable stdout")
switch verdict.verdict: case "allow": for entry in (verdict.consume_nonces or []): // Sec 7 host mode if not reserve_nonce_atomically(entry): reject("replay") // reserve ALL proceed() case "deny": reject(verdict.code) // branch on Sec 4.2 registry default: reject("unknown verdict")

